import zeros = require( '@stdlib/ndarray/base/zeros' );
import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import gfill = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( 'generic', [ 10 ], 'row-major' );
	const alpha = scalar2ndarray( 5.0, {
		'dtype': 'generic'
	});
	gfill( [ x, alpha ] ); // $ExpectType ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object...
{
	gfill( 'abc' ); // $ExpectError
	gfill( 5 ); // $ExpectError
	gfill( true ); // $ExpectError
	gfill( false ); // $ExpectError
	gfill( null ); // $ExpectError
	gfill( undefined ); // $ExpectError
	gfill( {} ); // $ExpectError
	gfill( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an insufficient number of arguments...
{
	gfill(); // $ExpectError
}

// The compiler throws an error if the function is provided too many arguments...
{
	const x = zeros( 'generic', [ 10 ], 'row-major' );
	const alpha = scalar2ndarray( 5.0, {
		'dtype': 'generic'
	});
	gfill( [ x, alpha ], 10 ); // $ExpectError
}
